import React, {useEffect, useState} from 'react';
import axios from 'axios';
import api from '../lib/api';
import { getCart as cartGet, addItem as cartAdd } from '../lib/cart';
import PublicHeader from '../components/PublicHeader';
import { API_BASE, MIDTRANS_CLIENT_KEY } from '../config';

function loadMidtrans(clientKey){
  return new Promise((resolve, reject) => {
    if (document.getElementById('midtrans-script')) return resolve();
    const s = document.createElement('script');
    s.id = 'midtrans-script';
    s.src = `https://app.sandbox.midtrans.com/snap/snap.js`; // change to production if needed
    s.setAttribute('data-client-key', clientKey);
    s.onload = () => resolve();
    s.onerror = reject;
    document.body.appendChild(s);
  });
}

export default function Home(){
  const [products, setProducts] = useState([]);
  const [cart, setCart] = useState([]);

  useEffect(()=>{
    axios.get(`${API_BASE}/products`).then(r=>setProducts(r.data.data || r.data));
  },[])

  // Init cart from localStorage and listen to updates
  useEffect(()=>{
    setCart(cartGet());
    const onUpd = ()=>{ setCart(cartGet()); };
    window.addEventListener('cart_updated', onUpd);
    return ()=> window.removeEventListener('cart_updated', onUpd);
  },[])

  function addToCart(p){
    const c = cartAdd(p, 1);
    setCart(c);
  }

  async function checkout(){
    if (!cart.length) return alert('Cart kosong');
    
    // Check if user logged in
    const token = localStorage.getItem('hr_token');
    if (!token) {
      if (window.confirm('Anda harus login terlebih dahulu. Login sekarang?')) {
        window.location.href = '/login';
      }
      return;
    }
    try {
      await loadMidtrans(MIDTRANS_CLIENT_KEY);
      const resp = await api.post(`/checkout`, {items:cart});
      const token_snap = resp.data.snap_token;
      const orderId = resp.data?.order?.order_number;
      if (!token_snap) return alert('Gagal membuat transaksi');
      window.snap.pay(token_snap, {
        onSuccess: function(result){
          alert('Pembayaran sukses');
          if (orderId) {
            // optional sync to ensure backend reflects final status when webhook is not reachable locally
            api.post('/midtrans/refresh', { order_id: orderId }).catch(()=>{});
          }
          setCart([]);
        },
        onPending: function(result){
          alert('Pembayaran pending');
          if (orderId) {
            api.post('/midtrans/refresh', { order_id: orderId }).catch(()=>{});
          }
        },
        onError: function(result){
          alert('Pembayaran error');
        }
      });
    } catch (err) {
      const data = err.response?.data;
      let msg = 'Checkout gagal';
      if (data) {
        if (typeof data.message === 'string') msg = data.message;
        else if (typeof data.details === 'string') msg = data.details;
        else if (typeof data.error === 'string') msg = data.error;
      }
      alert(msg);
      console.error('Checkout error:', err);
    }
  }

  return (
    <div className="font-sans">
      <PublicHeader/>
      <section className="bg-gray-50">
        <div className="container grid grid-cols-1 md:grid-cols-2 gap-8 py-12">
          <div className="flex items-center">
            <div>
              <h2 className="text-gray-700 text-xl">Temukan Dirimu</h2>
              <h1 className="text-4xl md:text-5xl font-extrabold tracking-tight">Tampilan & Gaya</h1>
              <button onClick={()=>window.scrollTo({top:400, behavior:'smooth'})} className="btn btn-accent mt-6 rounded-full">Temukan Sekarang</button>
            </div>
          </div>
          <div className="flex items-center justify-center">
            <div className="w-full max-w-md md:max-w-lg aspect-[4/3] bg-gray-200 rounded-xl overflow-hidden">
              <img src="/hero-sample.jpg" alt="hero" className="w-full h-full object-cover" />
            </div>
          </div>
        </div>
      </section>

      <section className="container py-10">
        <div className="flex items-end justify-between mb-6">
          <h2 className="text-2xl font-semibold">Produk</h2>
          <a href="/cart" className="text-sm underline">Lihat Keranjang</a>
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
          {products.map(p => (
            <div key={p.id} className="card overflow-hidden">
              <div className="aspect-[4/3] bg-gray-100">
                <img src={p.image||'/placeholder.png'} alt="p" className="w-full h-full object-cover" />
              </div>
              <div className="p-4">
                <h3 className="font-semibold line-clamp-1">{p.name}</h3>
                <p className="text-sm text-gray-600 mb-3">Rp {p.price}</p>
                <button className="btn btn-primary w-full" onClick={()=>addToCart(p)}>Tambah ke Keranjang</button>
              </div>
            </div>
          ))}
        </div>
      </section>

      {/* Floating cart removed as requested */}
    </div>
  )
}
